import java.util.*;

public class Main {
    static List<String> tokens;
    static int n;
    static long[] num;
    static char[] op;
    static long[][] dpMax, dpMin;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();
        sc.close();

        // Tokenize
        tokens = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '+' || c == '-' || c == '*') {
                if (sb.length() > 0) {
                    tokens.add(sb.toString());
                    sb.setLength(0);
                }
                tokens.add(String.valueOf(c));
            } else {
                sb.append(c);
            }
        }
        if (sb.length() > 0) {
            tokens.add(sb.toString());
        }

        n = (tokens.size() + 1) / 2;
        num = new long[n];
        op = new char[n - 1];

        int idxNum = 0, idxOp = 0;
        for (String t : tokens) {
            if (t.equals("+") || t.equals("-") || t.equals("*")) {
                op[idxOp++] = t.charAt(0);
            } else {
                num[idxNum++] = Long.parseLong(t);
            }
        }

        dpMax = new long[n][n];
        dpMin = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(dpMax[i], Long.MIN_VALUE);
            Arrays.fill(dpMin[i], Long.MAX_VALUE);
            dpMax[i][i] = num[i];
            dpMin[i][i] = num[i];
        }

        // DP over intervals
        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                for (int k = i; k < j; k++) {
                    long a = dpMax[i][k], b = dpMin[i][k];
                    long c = dpMax[k + 1][j], d = dpMin[k + 1][j];
                    char oper = op[k];
                    long[] vals = new long[4];
                    vals[0] = apply(oper, a, c);
                    vals[1] = apply(oper, a, d);
                    vals[2] = apply(oper, b, c);
                    vals[3] = apply(oper, b, d);
                    for (long v : vals) {
                        dpMax[i][j] = Math.max(dpMax[i][j], v);
                        dpMin[i][j] = Math.min(dpMin[i][j], v);
                    }
                }
            }
        }

        // Collect distinct possible results
        Set<Long> results = new HashSet<>();
        collect(0, n - 1, results);
        System.out.println(results.size());
    }

    static void collect(int l, int r, Set<Long> set) {
        if (l == r) {
            set.add(num[l]);
            return;
        }
        for (int k = l; k < r; k++) {
            char oper = op[k];
            // All combos of left and right
            Set<Long> leftSet = new HashSet<>();
            Set<Long> rightSet = new HashSet<>();
            collect(l, k, leftSet);
            collect(k + 1, r, rightSet);
            for (long x : leftSet) {
                for (long y : rightSet) {
                    set.add(apply(oper, x, y));
                }
            }
        }
    }

    static long apply(char op, long a, long b) {
        switch (op) {
            case '+': return a + b;
            case '-': return a - b;
            case '*': return a * b;
        }
        return 0;
    }
}

