public class Main {
    static Set<String> results = new HashSet<>();

    static long gcd(long a, long b) {
        a = Math.abs(a); b = Math.abs(b);
        while(b != 0) { long t = b; b = a%b; a = t; }
        return a;
    }

    // Rational: [num, den] with den > 0
    static long[] makeRat(long n, long d) {
        if(d < 0) { n = -n; d = -d; }
        long g = gcd(Math.abs(n), d);
        return new long[]{n/g, d/g};
    }

    static long[] applyOp(long[] a, long[] b, char op) {
        if(op == '+') return makeRat(a[0]*b[1] + b[0]*a[1], a[1]*b[1]);
        if(op == '-') return makeRat(a[0]*b[1] - b[0]*a[1], a[1]*b[1]);
        if(op == '*') return makeRat(a[0]*b[0], a[1]*b[1]);
        if(op == '/') {
            if(b[0] == 0) return null; // division by zero
            return makeRat(a[0]*b[1], a[1]*b[0]);
        }
        return null;
    }

    static void solve(List<long[]> vals, List<Character> ops) {
        if(ops.isEmpty()) {
            long[] v = vals.get(0);
            results.add(v[0] + "/" + v[1]);
            return;
        }
        for(int i = 0; i < ops.size(); i++) {
            long[] res = applyOp(vals.get(i), vals.get(i+1), ops.get(i));
            if(res == null) continue;
            List<long[]> newVals = new ArrayList<>(vals);
            newVals.remove(i+1);
            newVals.set(i, res);
            List<Character> newOps = new ArrayList<>(ops);
            newOps.remove(i);
            solve(newVals, newOps);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while(sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if(line.isEmpty()) continue;
            results.clear();
            List<long[]> vals = new ArrayList<>();
            List<Character> ops = new ArrayList<>();
            // parse
            int i = 0;
            while(i < line.length()) {
                int j = i;
                if(line.charAt(j) == '-' || Character.isDigit(line.charAt(j))) j++;
                while(j < line.length() && Character.isDigit(line.charAt(j))) j++;
                vals.add(makeRat(Long.parseLong(line.substring(i, j)), 1));
                i = j;
                if(i < line.length()) { ops.add(line.charAt(i)); i++; }
            }
            solve(vals, ops);
            System.out.println(results.size());
        }
    }
