/*
 *  Count distinct values obtainable by parenthesizing an expression
 *  consisting of integers and binary operators +, -, *, /.
 *
 *  Division is integer division truncated toward zero (Java semantics).
 *  Any intermediate step dividing by zero is invalid.
 *
 *  We compute for every interval [l..r] of numbers the set of all values
 *  obtainable from that subexpression. Transition:
 *      values[l][r] = union over split k of combine(values[l][k], op[k], values[k+1][r])
 *
 *  Since all intermediate absolute values are guaranteed <= 1e9 for every
 *  valid calculation order, int is sufficient.
 *
 *  Input format assumed:
 *    first line: integer T
 *    next T lines: one expression per line
 *
 *  If the judge instead provides a single expression without T, this parser
 *  also handles it.
 */
public class Main {
    static class FastReader {
        private final BufferedReader br;
        private String firstLineUsed = null;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextNonEmptyLine() throws IOException {
            String s;
            while ((s = br.readLine()) != null) {
                if (!s.trim().isEmpty()) return s.trim();
            }
            return null;
        }
    }

    static class ParsedExpr {
        int[] nums;
        char[] ops;
        ParsedExpr(int[] nums, char[] ops) {
            this.nums = nums;
            this.ops = ops;
        }
    }

    static ParsedExpr parseExpression(String s) {
        ArrayList<Integer> nums = new ArrayList<>();
        ArrayList<Character> ops = new ArrayList<>();

        int i = 0, n = s.length();
        while (i < n) {
            while (i < n && s.charAt(i) == ' ') i++;
            int sign = 1;

            // Optional unary sign for number
            if (i < n && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
                if (nums.isEmpty() || (!ops.isEmpty() && nums.size() == ops.size())) {
                    if (s.charAt(i) == '-') sign = -1;
                    i++;
                    while (i < n && s.charAt(i) == ' ') i++;
                }
            }

            long val = 0;
            while (i < n && Character.isDigit(s.charAt(i))) {
                val = val * 10 + (s.charAt(i) - '0');
                i++;
            }
            nums.add((int)(sign * val));

            while (i < n && s.charAt(i) == ' ') i++;
            if (i < n) {
                char c = s.charAt(i);
                if (c == '+' || c == '-' || c == '*' || c == '/') {
                    ops.add(c);
                    i++;
                }
            }
        }

        int[] a = new int[nums.size()];
        for (int j = 0; j < nums.size(); j++) a[j] = nums.get(j);
        char[] b = new char[ops.size()];
        for (int j = 0; j < ops.size(); j++) b[j] = ops.get(j);
        return new ParsedExpr(a, b);
    }

    static int apply(int x, int y, char op) {
        switch (op) {
            case '+': return x + y;
            case '-': return x - y;
            case '*': return x * y;
            default: return x / y; // y != 0 ensured before calling
        }
    }

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        String first = fr.nextNonEmptyLine();
        if (first == null) return;

        ArrayList<String> expressions = new ArrayList<>();

        boolean firstIsInt = true;
        int T = 0;
        try {
            T = Integer.parseInt(first);
        } catch (Exception e) {
            firstIsInt = false;
        }

        if (firstIsInt) {
            for (int i = 0; i < T; i++) {
                String line = fr.nextNonEmptyLine();
                if (line == null) line = "";
                expressions.add(line);
            }
        } else {
            expressions.add(first);
            String line;
            while ((line = fr.nextNonEmptyLine()) != null) expressions.add(line);
        }

        StringBuilder out = new StringBuilder();

        for (String expr : expressions) {
            ParsedExpr pe = parseExpression(expr);
            int[] nums = pe.nums;
            char[] ops = pe.ops;
            int n = nums.length;

            @SuppressWarnings("unchecked")
            HashSet<Integer>[][] dp = new HashSet[n][n];

            for (int i = 0; i < n; i++) {
                dp[i][i] = new HashSet<>();
                dp[i][i].add(nums[i]);
            }

            for (int len = 2; len <= n; len++) {
                for (int l = 0; l + len - 1 < n; l++) {
                    int r = l + len - 1;
                    HashSet<Integer> set = new HashSet<>();

                    for (int k = l; k < r; k++) {
                        HashSet<Integer> left = dp[l][k];
                        HashSet<Integer> right = dp[k + 1][r];
                        char op = ops[k];

                        for (int a : left) {
                            for (int b : right) {
                                if (op == '/' && b == 0) continue;
                                set.add(apply(a, b, op));
                            }
                        }
                    }
                    dp[l][r] = set;
                }
            }

            out.append(dp[0][n - 1].size()).append('\n');
        }

        System.out.print(out.toString());
    }
}

