            exprs = lines[1:]
        else:
            exprs = lines
    else:
        exprs = lines

    out = []
    for s in exprs:
        nums = []
        ops = []
        i = 0
        n = len(s)

        # parse expression of non-negative integers and binary operators + - * /
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                nums.append(int(s[i:j]))
                i = j
            else:
                ops.append(s[i])
                i += 1

        m = len(nums)

        @lru_cache(None)
        def solve(l, r):
            # returns frozenset of all possible results for nums[l..r]
            if l == r:
                return frozenset((nums[l],))
            res = set()
            for k in range(l, r):
                left = solve(l, k)
                right = solve(k + 1, r)
                op = ops[k]
                if op == '+':
                    for a in left:
                        for b in right:
                            res.add(a + b)
                elif op == '-':
                    for a in left:
                        for b in right:
                            res.add(a - b)
                elif op == '*':
                    for a in left:
                        for b in right:
                            res.add(a * b)
                else:  # '/'
                    for a in left:
                        for b in right:
                            if b != 0 and a % b == 0:
                                res.add(a // b)
            return frozenset(res)

        out.append(str(len(solve(0, m - 1))))

    sys.stdout.write("\n".join(out))

