#include <bits/stdc++.h>
using namespace std;

// Token types
enum TokenType { NUMBER, PLUS, MINUS, MULTIPLY, DIVIDE, LPAREN, RPAREN, END };

struct Token {
    TokenType type;
    int64_t value; // for NUMBER
};

// Lexer for expression
class Lexer {
public:
    Lexer(const string& s) : s(s), pos(0) {}
    Token nextToken() {
        while (pos < (int)s.size() && s[pos] == ' ') pos++;
        if (pos >= (int)s.size()) return {END, 0};
        char c = s[pos];
        if (isdigit(c)) {
            int64_t val = 0;
            while (pos < (int)s.size() && isdigit(s[pos])) {
                val = val * 10 + (s[pos] - '0');
                pos++;
            }
            return {NUMBER, val};
        }
        pos++;
        switch(c) {
            case '+': return {PLUS, 0};
            case '-': return {MINUS, 0};
            case '*': return {MULTIPLY, 0};
            case '/': return {DIVIDE, 0};
            case '(': return {LPAREN, 0};
            case ')': return {RPAREN, 0};
            default: return {END, 0};
        }
    }
private:
    string s;
    int pos;
};

// Expression with parentheses: we parse into tokens and then generate all possible evaluation trees
struct ExprNode {
    bool isLeaf;
    int64_t value; // if leaf
    char op;       // if internal
    shared_ptr<ExprNode> left, right;
};

// Parse expression (handles + - at top level, then * /, then parentheses/numbers)
// Returns list of tokens for the whole expression
vector<Token> tokenize(const string& s) {
    Lexer lex(s);
    vector<Token> tokens;
    Token t = lex.nextToken();
    while (t.type != END) {
        tokens.push_back(t);
        t = lex.nextToken();
    }
    return tokens;
}

// We'll generate all possible binary tree structures from a sequence of tokens (numbers and operators)
// The tokens are already in infix order (with parentheses removed, but we keep parentheses to structure parsing)
// Better approach: generate all full binary trees from the list of numbers and operators.
// We'll do recursive splitting on operators, considering parentheses.

// Given tokens from l to r (inclusive), generate all possible expression values
set<int64_t> solveRange(const vector<Token>& tokens, int l, int r) {
    set<int64_t> res;
    if (l == r) {
        // single number
        if (tokens[l].type == NUMBER) {
            res.insert(tokens[l].value);
        }
        return res;
    }
    // Try splitting at each operator (at top level, ignoring parentheses)
    // We need to respect parentheses: find matching pairs
    // We'll process from left to right, keeping track of parentheses depth
    int depth = 0;
    for (int i = l; i <= r; i++) {
        if (tokens[i].type == LPAREN) depth++;
        else if (tokens[i].type == RPAREN) depth--;
        if (depth == 0 && (tokens[i].type == PLUS || tokens[i].type == MINUS || 
                           tokens[i].type == MULTIPLY || tokens[i].type == DIVIDE)) {
            // split at i
            auto leftSet = solveRange(tokens, l, i-1);
            auto rightSet = solveRange(tokens, i+1, r);
            for (auto a : leftSet) {
                for (auto b : rightSet) {
                    switch(tokens[i].type) {
                        case PLUS: res.insert(a + b); break;
                        case MINUS: res.insert(a - b); break;
                        case MULTIPLY: res.insert(a * b); break;
                        case DIVIDE: if (b != 0) res.insert(a / b); break;
                    }
                }
            }
        }
    }
    // Also handle parenthesized subexpression: if the whole range is wrapped in parentheses
    if (tokens[l].type == LPAREN && tokens[r].type == RPAREN) {
        // check if parentheses match from l to r
        int d = 0;
        bool ok = true;
        for (int i = l; i <= r; i++) {
            if (tokens[i].type == LPAREN) d++;
            else if (tokens[i].type == RPAREN) d--;
            if (d == 0 && i < r) { ok = false; break; }
        }
        if (ok && d == 0) {
            auto inner = solveRange(tokens, l+1, r-1);
            res.insert(inner.begin(), inner.end());
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string expr;
    getline(cin, expr);

    auto tokens = tokenize(expr);
    // Remove outer parentheses if present as a whole? We'll just call solveRange on full range.
    auto results = solveRange(tokens, 0, (int)tokens.size()-1);

    cout << results.size() << "\n";
    return 0;
}

