using ll = long long;

struct ResultSet {
    vector<ll> v;
};

static inline vector<ll> merge_unique(vector<ll> a) {
    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());
    return a;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (cin >> s) {
        vector<ll> nums;
        vector<char> ops;

        int n = (int)s.size();
        for (int i = 0; i < n; ) {
            if (isdigit(s[i])) {
                ll x = 0;
                while (i < n && isdigit(s[i])) {
                    x = x * 10 + (s[i] - '0');
                    ++i;
                }
                nums.push_back(x);
            } else {
                ops.push_back(s[i]);
                ++i;
            }
        }

        int m = (int)nums.size();
        vector<vector<vector<ll>>> dp(m, vector<vector<ll>>(m));

        for (int i = 0; i < m; ++i) dp[i][i] = {nums[i]};

        for (int len = 2; len <= m; ++len) {
            for (int l = 0; l + len - 1 < m; ++l) {
                int r = l + len - 1;
                vector<ll> cur;

                for (int k = l; k < r; ++k) {
                    char op = ops[k];
                    const auto &A = dp[l][k];
                    const auto &B = dp[k + 1][r];

                    for (ll x : A) {
                        for (ll y : B) {
                            if (op == '+') cur.push_back(x + y);
                            else if (op == '-') cur.push_back(x - y);
                            else if (op == '*') cur.push_back(x * y);
                            else if (op == '/') {
                                if (y != 0) cur.push_back(x / y); // C++ integer division truncates toward zero
                            }
                        }
                    }
                }

                dp[l][r] = merge_unique(move(cur));
            }
        }

        cout << dp[0][m - 1].size() << '\n';
    }

    return 0;
}

