}

Fraction reduce(Fraction f) {
    if (f.den < 0) {
        f.num = -f.num;
        f.den = -f.den;
    }
    long long g = gcd(llabs(f.num), llabs(f.den));
    f.num /= g;
    f.den /= g;
    return f;
}

Fraction add(Fraction a, Fraction b) {
    Fraction res;
    res.num = a.num * b.den + b.num * a.den;
    res.den = a.den * b.den;
    return reduce(res);
}

Fraction sub(Fraction a, Fraction b) {
    Fraction res;
    res.num = a.num * b.den - b.num * a.den;
    res.den = a.den * b.den;
    return reduce(res);
}

Fraction mul(Fraction a, Fraction b) {
    Fraction res;
    res.num = a.num * b.num;
    res.den = a.den * b.den;
    return reduce(res);
}

Fraction div(Fraction a, Fraction b) {
    Fraction res;
    res.num = a.num * b.den;
    res.den = a.den * b.num;
    return reduce(res);
}

typedef struct {
    Fraction val;
    int valid;
} Result;

int n;
char ops[MAX_N];
long long nums[MAX_N];
Result dp[MAX_MASK][MAX_N][MAX_N];

int compare(const void *a, const void *b) {
    Fraction *fa = (Fraction *)a;
    Fraction *fb = (Fraction *)b;
    if (fa->num * fb->den < fb->num * fa->den) return -1;
    if (fa->num * fb->den > fb->num * fa->den) return 1;
    return 0;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%lld", &nums[i]);
    }
    for (int i = 0; i < n - 1; i++) {
        scanf(" %c", &ops[i]);
    }

    // Initialize dp for single numbers
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                dp[mask][i][j].valid = 0;
            }
        }
        int mask = 1 << i;
        dp[mask][i][i].valid = 1;
        dp[mask][i][i].val.num = nums[i];
        dp[mask][i][i].val.den = 1;
    }

    // DP over subsets
    for (int mask = 1; mask < (1 << n); mask++) {
        // Get leftmost and rightmost indices
        int l = -1, r = -1;
        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                if (l == -1) l = i;
                r = i;
            }
        }
        if (l == r) continue; // single element already done

        // Try all possible last operations
        for (int op_idx = l; op_idx < r; op_idx++) {
            // Split mask into left and right parts
            // left part must contain l..op_idx, right part op_idx+1..r
            int left_mask = 0, right_mask = 0;
            for (int i = l; i <= op_idx; i++) {
                if (mask & (1 << i)) left_mask |= (1 << i);
            }
            for (int i = op_idx + 1; i <= r; i++) {
                if (mask & (1 << i)) right_mask |= (1 << i);
            }
            if (left_mask == 0 || right_mask == 0) continue;
            if ((left_mask | right_mask) != mask) continue;
            if ((left_mask & right_mask) != 0) continue;

            // For each possible left result and right result
            for (int l1 = l; l1 <= op_idx; l1++) {
                if (!(left_mask & (1 << l1))) continue;
                for (int r1 = l1; r1 <= op_idx; r1++) {
                    if (!dp[left_mask][l1][r1].valid) continue;
                    if ((left_mask & ((1 << (r1 + 1)) - (1 << l1))) != 
                         ((1 << (r1 + 1)) - (1 << l1))) continue; // must be contiguous
                    for (int l2 = op_idx + 1; l2 <= r; l2++) {
                        if (!(right_mask & (1 << l2))) continue;
                        for (int r2 = l2; r2 <= r; r2++) {
                            if (!dp[right_mask][l2][r2].valid) continue;
                            if ((right_mask & ((1 << (r2 + 1)) - (1 << l2))) != 
                                 ((1 << (r2 + 1)) - (1 << l2))) continue;

                            Fraction res;
                            int valid_op = 1;
                            char op = ops[op_idx];
                            if (op == '+') {
                                res = add(dp[left_mask][l1][r1].val, dp[right_mask][l2][r2].val);
                            } else if (op == '-') {
                                res = sub(dp[left_mask][l1][r1].val, dp[right_mask][l2][r2].val);
                            } else if (op == '*') {
                                res = mul(dp[left_mask][l1][r1].val, dp[right_mask][l2][r2].val);
                            } else if (op == '/') {
                                if (dp[right_mask][l2][r2].val.num == 0) {
                                    valid_op = 0;
                                } else {
                                    res = div(dp[left_mask][l1][r1].val, dp[right_mask][l2][r2].val);
                                }
                            }
                            if (!valid_op) continue;

                            // Store result for the combined mask
                            int new_l = l1 < l2 ? l1 : l2;
                            int new_r = r1 > r2 ? r1 : r2;
                            if (!dp[mask][new_l][new_r].valid) {
                                dp[mask][new_l][new_r].valid = 1;
                                dp[mask][new_l][new_r].val = res;
                            } else {
                                // Check if same value already stored (optional, we keep first)
                                // Since we only need count of distinct final values, we can just store
                                // and later collect all possible final values
                            }
                        }
                    }
                }
            }
        }
    }

    // Collect all possible final results
    Fraction results[10000];
    int cnt = 0;
    int full_mask = (1 << n) - 1;
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (dp[full_mask][i][j].valid) {
                results[cnt++] = dp[full_mask][i][j].val;
            }
        }
    }

    // Sort and count distinct
    qsort(results, cnt, sizeof(Fraction), compare);
    int distinct = 0;
    for (int i = 0; i < cnt; i++) {
        if (i == 0 || results[i].num * results[i-1].den != results[i-1].num * results[i].den) {
            distinct++;
        }
    }

    printf("%d\n", distinct);
    return 0;
}

