#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct {
    ll *a;
    int n, cap;
} Vec;

static void vec_init(Vec *v) {
    v->a = NULL;
    v->n = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, ll x) {
    if (v->n == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 8;
        v->a = (ll*)realloc(v->a, sizeof(ll) * v->cap);
    }
    v->a[v->n++] = x;
}

static int cmp_ll(const void *p, const void *q) {
    ll x = *(const ll*)p, y = *(const ll*)q;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static void vec_sort_unique(Vec *v) {
    if (v->n == 0) return;
    qsort(v->a, v->n, sizeof(ll), cmp_ll);
    int m = 1;
    for (int i = 1; i < v->n; i++) {
        if (v->a[i] != v->a[m - 1]) v->a[m++] = v->a[i];
    }
    v->n = m;
}

static void vec_free(Vec *v) {
    free(v->a);
    v->a = NULL;
    v->n = v->cap = 0;
}

static ll apply_op(ll x, ll y, char op, int *ok) {
    *ok = 1;
    if (op == '+') return x + y;
    if (op == '-') return x - y;
    if (op == '*') return x * y;
    if (op == '/') {
        if (y == 0) {
            *ok = 0;
            return 0;
        }
        return x / y; /* C integer division truncates toward zero */
    }
    *ok = 0;
    return 0;
}

int main(void) {
    char s[1005];
    while (scanf("%s", s) == 1) {
        int len = (int)strlen(s);

        ll nums[205];
        char ops[205];
        int nnum = 0, nop = 0;

        int i = 0;
        while (i < len) {
            ll val = 0;
            while (i < len && s[i] >= '0' && s[i] <= '9') {
                val = val * 10 + (s[i] - '0');
                i++;
            }
            nums[nnum++] = val;
            if (i < len) ops[nop++] = s[i++];
        }

        static Vec dp[205][205];
        for (int l = 0; l < nnum; l++) {
            for (int r = 0; r < nnum; r++) {
                vec_init(&dp[l][r]);
            }
        }

        for (int j = 0; j < nnum; j++) {
            vec_push(&dp[j][j], nums[j]);
        }

        for (int sz = 2; sz <= nnum; sz++) {
            for (int l = 0; l + sz - 1 < nnum; l++) {
                int r = l + sz - 1;
                Vec cur;
                vec_init(&cur);

                for (int k = l; k < r; k++) {
                    Vec *A = &dp[l][k];
                    Vec *B = &dp[k + 1][r];
                    char op = ops[k];
                    for (int x = 0; x < A->n; x++) {
                        for (int y = 0; y < B->n; y++) {
                            int ok;
                            ll z = apply_op(A->a[x], B->a[y], op, &ok);
                            if (ok) vec_push(&cur, z);
                        }
                    }
                }

                vec_sort_unique(&cur);
                dp[l][r] = cur;
            }
        }

        printf("%d\n", dp[0][nnum - 1].n);

        for (int l = 0; l < nnum; l++) {
            for (int r = 0; r < nnum; r++) {
                vec_free(&dp[l][r]);
            }
        }
    }
    return 0;
}
